<?php
require_once __DIR__.'/GenericStateService.php';
final class SimulationService {
    public static function create(string $plotCode='CONCEALED_FAILURE', int $duration=300,array $controllers=[]): int {
        $pdo=db();$q=$pdo->prepare('SELECT * FROM plots WHERE code=? AND status IN ("draft","active")');$q->execute([$plotCode]);$plot=$q->fetch();if(!$plot)throw new RuntimeException('Plot not found.');
        $pdo->beginTransaction();
        try{
            $pdo->prepare('INSERT INTO simulations(plot_id,duration_seconds,mode,status,current_phase) VALUES(?,?,"MANUAL","READY","SETUP")')->execute([$plot['plot_id'],$duration]);$sid=(int)$pdo->lastInsertId();
            $f=$pdo->prepare('SELECT * FROM plot_factors WHERE plot_id=?');$f->execute([$plot['plot_id']]);foreach($f->fetchAll()as$r)$pdo->prepare('INSERT INTO simulation_factors(simulation_id,factor_code,label,current_value,min_value,max_value) VALUES(?,?,?,?,?,?)')->execute([$sid,$r['factor_code'],$r['label'],$r['initial_value'],$r['min_value'],$r['max_value']]);
            if(class_exists('GenericStateService'))GenericStateService::initializePlotState($sid);
            $roles=$pdo->prepare('SELECT * FROM plot_roles WHERE plot_id=? AND active=1 AND simulation_active=1 ORDER BY CASE WHEN role_type="PLAYER" THEN 0 ELSE 1 END,slot_no');$roles->execute([$plot['plot_id']]);$activeRoles=$roles->fetchAll();
            $playerCount=count(array_filter($activeRoles,fn($r)=>$r['role_type']==='PLAYER'));$npcCount=count(array_filter($activeRoles,fn($r)=>$r['role_type']==='NPC'));$allowedNpcs=$playerCount===1?2:1;
            if($npcCount>$allowedNpcs)throw new RuntimeException('Story cast exceeds the active NPC budget: solo allows 2 NPCs; multiplayer allows 1 NPC.');
            foreach($activeRoles as$r){
                $npcReasoner=strtolower(trim((string)getenv('GAME2_SIM_NPC_REASONER')));$defaultController=$r['role_type']==='NPC'&&$npcReasoner==='weighted'?'HUMAN':($r['role_type']==='NPC'?'AI':'HUMAN');$controller=strtoupper((string)($controllers[$r['role_code']]??$defaultController));if(!in_array($controller,['HUMAN','AI'],true))$controller=$defaultController;
                $pdo->prepare('INSERT INTO characters(simulation_id,plot_role_id,actor_type,controller_type,slot_no,name,pronoun_set,description,private_knowledge,current_location,goal_text,fear_text) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$sid,$r['plot_role_id'],$r['role_type'],$controller,$r['slot_no'],$r['name'],$r['pronoun_set']??'IT',$r['public_description'],$r['private_knowledge'],$r['starting_location'],$r['goal_text'],$r['fear_text']]);$cid=(int)$pdo->lastInsertId();
                $s=$pdo->prepare('SELECT * FROM plot_role_stats WHERE plot_role_id=? ORDER BY plot_role_stat_id');$s->execute([$r['plot_role_id']]);foreach($s->fetchAll()as$st)$pdo->prepare('INSERT INTO character_stats(character_id,stat_code,label,current_value) VALUES(?,?,?,?)')->execute([$cid,$st['stat_code'],$st['label'],$st['initial_value']]);
                if($r['private_knowledge'])$pdo->prepare('INSERT INTO character_knowledge(character_id,knowledge_key,knowledge_text,state,confidence,learned_at_second) VALUES(?,?,?,?,100,0)')->execute([$cid,'START_'.$r['role_code'],$r['private_knowledge'],'KNOWN']);
                $pdo->prepare('INSERT INTO character_history(simulation_id,character_id,event_second,history_type,title,detail_text) VALUES(?,?,0,"EXPERIENCED","Initial State",?)')->execute([$sid,$cid,'Location: '.$r['starting_location'].' | Goal: '.$r['goal_text'].' | Fear: '.($r['fear_text']?:'None specified')]);
            }
            $chars=$pdo->prepare('SELECT character_id FROM characters WHERE simulation_id=?');$chars->execute([$sid]);$ids=array_column($chars->fetchAll(),'character_id');foreach($ids as$a)foreach($ids as$b)if($a!==$b)$pdo->prepare('INSERT INTO relationships(simulation_id,from_character_id,to_character_id,trust,suspicion,loyalty) VALUES(?,?,?,?,?,?)')->execute([$sid,$a,$b,50,10,50]);
            $pdo->commit();return$sid;
        }catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
    }
    public static function start(int $sid): void {db()->prepare('UPDATE simulations SET status="RUNNING",current_phase="EXPOSITION",started_at_utc=UTC_TIMESTAMP() WHERE simulation_id=? AND status="READY"')->execute([$sid]);self::generateDueEvents($sid,0,'EXPOSITION');}
    public static function advance(int $sid,int $seconds=30): void {
        $pdo=db();$sim=self::simulation($sid);if($sim['status']==='READY'){self::start($sid);$sim=self::simulation($sid);}if($sim['status']!=='RUNNING')return;
        $next=min((int)$sim['duration_seconds'],(int)$sim['elapsed_seconds']+$seconds);$phase=self::phaseFor($next,(int)$sim['duration_seconds']);
        if(class_exists('BehaviorService'))BehaviorService::expire($sid,$next);
        $pdo->prepare('UPDATE simulations SET elapsed_seconds=?,current_phase=? WHERE simulation_id=?')->execute([$next,$phase,$sid]);self::generateDueEvents($sid,$next,$phase);
        if(class_exists('TriggeredTransitionService'))TriggeredTransitionService::evaluate($sid,$next,null);
        if(class_exists('DynamicOpportunityService'))DynamicOpportunityService::reconcile($sid);
        if($next>=(int)$sim['duration_seconds']){$pdo->prepare('UPDATE simulations SET status="COMPLETE",current_phase="COMPLETE",ended_at_utc=UTC_TIMESTAMP() WHERE simulation_id=?')->execute([$sid]);if(class_exists('BehaviorService'))BehaviorService::expire($sid,$next+1);}
    }
    public static function choose(int $sid,int $decisionId,string $optionCode): void {if(!class_exists('BehaviorService'))throw new RuntimeException('Behavior engine is unavailable.');BehaviorService::choose($sid,$decisionId,$optionCode);}
    private static function phaseFor(int $elapsed,int $duration): string {$p=$duration?($elapsed/$duration):1;return$p<.18?'EXPOSITION':($p<.42?'INCITING_INCIDENT':($p<.72?'RISING_ACTION':($p<.92?'CLIMAX':'RESOLUTION')));}
    private static function generateDueEvents(int $sid,int $elapsed,string $phase): void {$pdo=db();$sim=self::simulation($sid);$q=$pdo->prepare('SELECT pwe.* FROM plot_world_events pwe LEFT JOIN simulation_events se ON se.simulation_id=? AND se.event_code=pwe.event_code WHERE pwe.plot_id=? AND pwe.active=1 AND pwe.event_second<=? AND se.event_id IS NULL ORDER BY pwe.event_second,pwe.sort_order,pwe.plot_world_event_id');$q->execute([$sid,$sim['plot_id'],$elapsed]);foreach($q->fetchAll() as $event)self::worldEvent($sid,(int)$event['event_second'],(string)$event['phase'],(string)$event['event_code'],(string)$event['headline'],(string)$event['event_text']);}
    private static function worldEvent(int $sid,int $second,string $phase,string $code,string $headline,string $text): int {$pdo=db();$q=$pdo->prepare('SELECT event_id FROM simulation_events WHERE simulation_id=? AND event_code=?');$q->execute([$sid,$code]);$id=(int)$q->fetchColumn();if($id)return$id;$pdo->prepare('INSERT INTO simulation_events(simulation_id,event_second,phase,event_type,event_code,headline,event_text,visibility) VALUES(?,?,?,?,?,?,?,"WORLD")')->execute([$sid,$second,$phase,'WORLD',$code,$headline,$text]);$id=(int)$pdo->lastInsertId();self::applyWorldEventEffects($sid,$code,$second,$id);$sim=self::simulation($sid);$pq=$pdo->prepare('SELECT COUNT(*) FROM plot_event_perceptions WHERE plot_id=? AND event_code=?');$pq->execute([$sim['plot_id'],$code]);$hasSpecific=(int)$pq->fetchColumn()>0;if(!$hasSpecific){$chars=$pdo->prepare('SELECT character_id FROM characters WHERE simulation_id=?');$chars->execute([$sid]);foreach($chars->fetchAll()as$c)$pdo->prepare('INSERT INTO character_history(simulation_id,character_id,event_id,event_second,history_type,title,detail_text) VALUES(?,?,?,?,"EXPERIENCED",?,?)')->execute([$sid,$c['character_id'],$id,$second,$headline,$text]);}if(class_exists('BehaviorService'))BehaviorService::onWorldEvent($sid,$id,$code,$second);return$id;}
    private static function applyWorldEventEffects(int $sid,string $eventCode,int $second,int $eventId): void
    {
        $pdo=db();try{$q=$pdo->prepare('SELECT pwee.* FROM plot_world_event_effects pwee JOIN simulations s ON s.plot_id=pwee.plot_id WHERE s.simulation_id=? AND pwee.event_code=? AND pwee.active=1 ORDER BY pwee.sort_order,pwee.world_event_effect_id');$q->execute([$sid,$eventCode]);}catch(Throwable $e){return;}
        foreach($q->fetchAll()as$effect){if(!self::worldEventEffectConditionsPass($sid,(int)$effect['world_event_effect_id']))continue;$scope=(string)$effect['effect_scope'];$detail=(string)($effect['detail_text']??'');
            if($scope==='WORLD_STATE'){GenericStateService::setByKey($sid,(string)$effect['target_code'],(string)($effect['set_value']??''),$second,$detail);continue;}
            if($scope==='FACTOR'){$fq=$pdo->prepare('SELECT current_value,min_value,max_value FROM simulation_factors WHERE simulation_id=? AND factor_code=? FOR UPDATE');$fq->execute([$sid,$effect['target_code']]);$factor=$fq->fetch();if(!$factor)continue;$old=(int)$factor['current_value'];$new=max((int)$factor['min_value'],min((int)$factor['max_value'],$old+(int)$effect['delta_value']));if($new===$old)continue;$pdo->prepare('UPDATE simulation_factors SET current_value=? WHERE simulation_id=? AND factor_code=?')->execute([$new,$sid,$effect['target_code']]);$pdo->prepare('INSERT INTO simulation_factor_history(simulation_id,factor_code,old_value,new_value,event_second,source_type,source_id,detail_text) VALUES(?,?,?,?,?,"WORLD_EVENT",?,?)')->execute([$sid,$effect['target_code'],$old,$new,$second,$eventId,$detail?:null]);}
        }
    }
    private static function worldEventEffectConditionsPass(int $sid,int $effectId): bool
    {
        $q=db()->prepare('SELECT state_key,operator,compare_value FROM plot_world_event_effect_conditions WHERE world_event_effect_id=? ORDER BY sort_order,world_event_effect_condition_id');$q->execute([$effectId]);foreach($q->fetchAll()as$condition)if(!GenericStateService::conditionPasses($sid,(string)$condition['state_key'],(string)$condition['operator'],$condition['compare_value']))return false;return true;
    }
    public static function snapshot(int $sid): array {$pdo=db();$s=$pdo->prepare('SELECT s.*,p.title,p.archetype,p.genre,p.setting_name,p.scenario_text FROM simulations s JOIN plots p ON p.plot_id=s.plot_id WHERE s.simulation_id=?');$s->execute([$sid]);$sim=$s->fetch();if(!$sim)throw new RuntimeException('Simulation not found.');$f=$pdo->prepare('SELECT * FROM simulation_factors WHERE simulation_id=? ORDER BY simulation_factor_id');$f->execute([$sid]);$c=$pdo->prepare('SELECT c.*,pr.starting_location AS initial_location,pr.goal_text AS initial_goal_text,pr.fear_text AS initial_fear_text FROM characters c JOIN plot_roles pr ON pr.plot_role_id=c.plot_role_id WHERE c.simulation_id=? ORDER BY CASE WHEN c.actor_type="PLAYER" THEN 0 ELSE 1 END,c.slot_no');$c->execute([$sid]);$chars=$c->fetchAll();foreach($chars as&$ch){$st=$pdo->prepare('SELECT cs.*,prs.initial_value FROM character_stats cs LEFT JOIN plot_role_stats prs ON prs.plot_role_id=? AND prs.stat_code=cs.stat_code WHERE cs.character_id=? ORDER BY cs.character_stat_id');$st->execute([$ch['plot_role_id'],$ch['character_id']]);$ch['stats']=$st->fetchAll();$h=$pdo->prepare('SELECT * FROM character_history WHERE character_id=? AND event_second<=? ORDER BY event_second,history_id');$h->execute([$ch['character_id'],$sim['elapsed_seconds']]);$ch['history']=$h->fetchAll();$d=$pdo->prepare('SELECT d.* FROM decisions d WHERE d.character_id=? AND d.status="OPEN" AND d.opens_at_second<=? ORDER BY d.opens_at_second,d.decision_id');$d->execute([$ch['character_id'],$sim['elapsed_seconds']]);$ch['open_decisions']=$d->fetchAll();foreach($ch['open_decisions']as&$dec){$o=$pdo->prepare('SELECT do.*,pdto.template_option_id,pdto.npc_weight FROM decision_options do JOIN decisions d ON d.decision_id=do.decision_id JOIN simulation_events se ON se.event_id=d.event_id JOIN characters c ON c.character_id=d.character_id JOIN plot_roles pr ON pr.plot_role_id=c.plot_role_id JOIN plot_decision_templates pdt ON pdt.plot_id=pr.plot_id AND pdt.role_code=pr.role_code AND pdt.event_code=se.event_code JOIN plot_decision_template_options pdto ON pdto.template_id=pdt.template_id AND pdto.option_code=do.option_code AND pdto.active=1 WHERE do.decision_id=? ORDER BY do.sort_order,do.decision_option_id');$o->execute([$dec['decision_id']]);$options=[];foreach($o->fetchAll()as$opt){if(class_exists('CausalService')&&!CausalService::optionAllowed($sid,(int)$opt['template_option_id']))continue;$options[]=$opt;}$dec['options']=$options;}unset($dec);$ch['open_decisions']=array_values(array_filter($ch['open_decisions'],fn($d)=>!empty($d['options'])));}unset($ch);$e=$pdo->prepare('SELECT se.*,c.name actor_name,c.controller_type actor_controller_type FROM simulation_events se LEFT JOIN characters c ON c.character_id=se.actor_character_id WHERE se.simulation_id=? AND se.visibility="WORLD" ORDER BY se.event_second,se.event_id');$e->execute([$sid]);return['simulation'=>$sim,'factors'=>$f->fetchAll(),'characters'=>$chars,'world'=>$e->fetchAll()];}
    private static function simulation(int $sid): array {$q=db()->prepare('SELECT * FROM simulations WHERE simulation_id=?');$q->execute([$sid]);$r=$q->fetch();if(!$r)throw new RuntimeException('Simulation not found.');return$r;}
}
